import itertools

def solve_small(N, s):
    # All 0-1 sequences of length N
    sequences = list(itertools.product([0, 1], repeat=N))

    # We need to find a partition of sequences into 2*N sets C_{i,v}
    # where i in {0, ..., N-1} and v in {0, 1}
    # Each C_{i,v} must be a subset of a face of dimension N-s
    # A face of dimension N-s is defined by s fixed coordinates.
    # For C_{i,v}, coordinate i must be fixed to v.

    # This is a search problem. Let's try to see if a solution exists for N=4, s=3.
    # The total number of sequences is 16. Each C_{i,v} has size at most 2^(N-s) = 2^1 = 2.
    # Since 2*N * 2^(N-s) = 8 * 2 = 16, each C_{i,v} must have exactly 2 elements.
    # And they must be disjoint.

    # So we need to partition 16 sequences into 8 pairs, such that
    # each pair (X, Y) has at least 3 common coordinates, and one of those is (i,v).
    # Let's try to find such a partition.

    from itertools import combinations

    all_pairs = list(combinations(sequences, 2))
    # Filter pairs that have at least 3 common coordinates
    valid_pairs = []
    for p in all_pairs:
        common = []
        for i in range(N):
            if p[0][i] == p[1][i]:
                common.append((i, p[0][i]))
        if len(common) >= s:
            valid_pairs.append((p, common))

    # Now we need to pick 8 disjoint pairs and assign them to (i,v)
    # This is still a big search. Let's try a simpler approach.
    # Let's use backtracking to find the partition.

    def backtrack(remaining_seqs, available_iv):
        if not remaining_seqs:
            return True

        seq = remaining_seqs[0]
        for (pair, common) in valid_pairs:
            if seq in pair:
                other = pair[1] if pair[0] == seq else pair[0]
                if other in remaining_seqs:
                    # Check if this pair can be assigned to any of the available (i,v)
                    for iv in available_iv:
                        if iv in common:
                            # Try assigning this pair to iv
                            new_remaining = [s for s in remaining_seqs if s != seq and s != other]
                            new_available = [iv_alt for iv_alt in available_iv if iv_alt != iv]
                            if backtrack(new_remaining, new_available):
                                return True
        return False

    available_iv = []
    for i in range(N):
        available_iv.append((i, 0))
        available_iv.append((i, 1))

    return backtrack(sequences, available_iv)

print(f"N=4, s=3: {solve_small(4, 3)}")

import itertools

def solve_small(N, s):
    sequences = list(itertools.product([0, 1], repeat=N))
    all_pairs = list(itertools.combinations(sequences, 2))
    valid_pairs = []
    for p in all_pairs:
        common = []
        for i in range(N):
            if p[0][i] == p[1][i]:
                common.append((i, p[0][i]))
        if len(common) >= s:
            valid_pairs.append((p, common))

    def backtrack(remaining_seqs, available_iv):
        if not remaining_seqs:
            return True

        seq = remaining_seqs[0]
        # We can either put seq in a pair or as a single element
        # But a single element is just a face of dimension N-s where s coordinates are fixed.
        # Let's try pairs first.
        for (pair, common) in valid_pairs:
            if seq in pair:
                other = pair[1] if pair[0] == seq else pair[0]
                if other in remaining_seqs:
                    for iv in available_iv:
                        if iv in common:
                            new_remaining = [s for s in remaining_seqs if s != seq and s != other]
                            new_available = [iv_alt for iv_alt in available_iv if iv_alt != iv]
                            if backtrack(new_remaining, new_available):
                                return True

        # Try as a single element
        for iv in available_iv:
            if seq[iv[0]] == iv[1]:
                new_remaining = [s for s in remaining_seqs if s != seq]
                new_available = [iv_alt for iv_alt in available_iv if iv_alt != iv]
                if backtrack(new_remaining, new_available):
                    return True
        return False

    available_iv = []
    for i in range(N):
        available_iv.append((i, 0))
        available_iv.append((i, 1))

    return backtrack(sequences, available_iv)

print(f"N=3, s=2: {solve_small(3, 2)}")
